Lemma poisoned_of_u8arr : forall m A k v, 0 <= A -> A mod 8 = 0 -> u8arr bsegs m (sh A) (repeat (b8 v) k) -> poisoned m A k v.
Proof. intros m A k v H0 H8 U8. split; [exact H0|]. split; [exact H8|]. exact U8. Qed.

(* [comment removed for export] *)
Lemma junk_of_rw_cells : forall m A cs n, rw_cells bsegs m A cs -> Z.of_nat (cells_size cs) = n -> junk m A n.
Proof. intros m A cs n RC E POS. rewrite <- E. exact (stk_of_rw_cells bsegs _ _ _ RC). Qed.


(* [comment removed for export] *)
Lemma free_ub8 : forall s m ch bs, AREP s m -> In ch (chunk_list (a_st s)) -> ch_state ch = CAllocated ->
  rw_cells bsegs m (ch_user_beg ch) [CB (Z.to_nat (ch_used ch)) bs] -> exists ub, rw_cells bsegs m (ch_user_beg ch) [CB 8 ub].
Proof.
  intros s m ch bs R CHIN ALLOC BLK. pose proof (proj1 R) as OK.
  pose proof R as RR. destruct RR as (_ & _ & _ & _ & _ & _ & _ & CHR & _). pose proof (CHR ch CHIN) as (_ & _ & STI & JR & _).
  rewrite ALLOC in STI. pose proof (record_ext s OK ch CHIN) as (E1 & E2 & E3 & _ & _ & E6 & E7 & E8 & E9).
  pose proof (chunk_geom s OK ch CHIN) as (_ & _ & _ & _ & G5 & G6 & _).
  pose proof (stk_of_rw_cells bsegs _ _ _ BLK) as SK. cbn [cells_size csize Nat.add] in SK.
  replace (ch_user_beg ch + Z.of_nat (Z.to_nat (ch_used ch) + 0)) with (ch_user_beg ch + ch_used ch) in SK by lia.
  destruct (Z.le_gt_cases 8 (ch_used ch)) as [LE|GT].
  - destruct (stk_split bsegs _ _ (ch_user_beg ch + 8) _ SK ltac:(lia)) as [SK1 _]. destruct (stk_cells _ _ _ SK1 ltac:(lia)) as [ub Hub].
    exists ub. replace (Z.to_nat (ch_user_beg ch + 8 - ch_user_beg ch)) with 8%nat in Hub by lia. exact Hub.
  - unfold AIMG_TOP in E1. acb.
    pose proof (junk_stk' _ _ _ JR ltac:(lia) ltac:(lia) ltac:(lia)) as SJ.
    replace (ch_user_beg ch + ch_used ch + (ch_end ch - (ch_user_beg ch + ch_used ch))) with (ch_end ch) in SJ by lia.
    destruct (stk_split bsegs _ _ (ch_user_beg ch + 8) _ SJ ltac:(lia)) as [SJ1 _].
    pose proof (stk_merge bsegs _ _ _ _ SK SJ1 ltac:(lia)) as SK8.
    destruct (stk_cells _ _ _ SK8 ltac:(lia)) as [ub Hub]. exists ub. replace (Z.to_nat (ch_user_beg ch + 8 - ch_user_beg ch)) with 8%nat in Hub by lia. exact Hub.
Qed.

