            (PositiveMap.add (ckey U) (qch ch) (as_chunks st)) tq' (as_gq st) true (as_maps st) (as_shadow st) (as_env st)
            (as_track_shadow st) (as_qmax st) (as_qmin st) (as_qcache st).
  Let st' := free_st'.
