  Hypothesis WM : wmono bsegs m m'.
  (* [comment removed for export] *)
  Hypothesis B1 : 0 <= b1 < 256 /\ b1 mod 128 = 17.
  Hypothesis HDR' : rw_cells bsegs m' (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)].
  Hypothesis UW' : rw_cells bsegs m' U [C8 (wz idv)].
  Hypothesis SHF' : u8arr bsegs m' (sh U) (repeat (b8 kAsanHeapFreeMagic) (Z.to_nat (nsh size))).
  Hypothesis FLG' : rw_cells bsegs m' AIAINIT [C1 (b8 1); C1 (b8 0); C2 (wz 0)].
  Hypothesis IA' : ia_after m'.      (* [comment removed for export] *)
  Hypothesis TST' : stk bsegs m' (TH + 2800) (TH + 3168).
  Hypothesis UNW' : rw_cells bsegs m' (TH + 3168) [C1 (b8 0)].
  Hypothesis CST' : junk m' (TH + 2768) 32.
  Hypothesis TQ' : rw_cells bsegs m' (TH + OT_TQ)
      [C8 (wz (zlen (qc_list tq'))); C8 (wz (hd 0 (map qb_addr (qc_list tq')))); C8 (wz (last (map qb_addr (qc_list tq')) 0)); C8 (wz (qc_bytes tq'))].
