    pose proof (chunk_geom s OK ch CHIN) as (G1 & G2 & G3 & G4 & G5 & G6 & _).
    pose proof (record_band s OK ch CHIN) as RB. unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AIMG_TOP, AHI_LO in RB. unfold AHI_LO in UHI.  (* [comment removed for export] *)
    clear - X1 X2 X3 X4 X5 X6 X7 X8 X9 G1 G2 G3 G4 G5 G6 RB UHI. subst U size. pose proof (aapp_env _ _ UHI ltac:(clear - G3 G5; lia)) as [UE _]. unfold AHI_LO, AIMG_TOP in *. repeat split; try assumption; lia.
  Qed.
  (* [comment removed for export] *)
  Let BND : 4096 <= TH /\ TH + 4096 <= aceil /\ 6832128 <= CTX /\ CTX + 160 <= aceil
            /\ 0x10007fff8000 <= sb /\ sb + 137438953472 + 4096 <= aceil /\ 6832128 <= a_pa s /\ a_pa s + 8388608 <= aceil
            /\ 6832144 <= U /\ U + round_up size 8 <= aceil /\ 1 <= size /\ size <= round_up size 8 /\ round_up size 8 = 8 * nsh size
            /\ 2148304896 <= sh U /\ sh U + nsh size <= 0x10007fff8000 /\ U mod 16 = 0 /\ (sh U + nsh size <= U - 16 \/ U + round_up size 8 <= sh U) /\ (U + round_up size 8 <= 2147446784 \/ 17594333495296 <= U - 16) /\ (ch_end ch <= 2147446784 \/ 17594333495296 <= ch_lo ch).
  Proof.
    pose proof PURE as (Z1 & Z2 & Z3 & Z4 & Z5 & Z6 & Y1 & Y2 & Y3 & Y4 & Y5 & Y6 & X1 & X2 & X3 & _).
    pose proof PL as (_ & _ & _ & P1 & P2 & P3 & _). apply aapp_env in P2; [| unfold kPtrArrayReserve; clear; lia].
    pose proof (record_band s OK ch CHIN) as RBB. unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AIMG_TOP, AHI_LO in RBB.   (* [comment removed for export] *)
    clear - RBB Z1 Z2 Z3 Z4 Z5 Z6 Y1 Y2 Y4 Y5 X1 X2 P2 P3.
    subst U size TH CTX sb. unfold AHI_LO, AIMG_TOP, kSpaceSize, kPageSize, kPtrArrayReserve in *.
    assert (SH : 2148304896 <= sh (ch_user_beg ch) /\ sh (ch_user_beg ch) + nsh (ch_used ch) <= 0x10007fff8000
                 /\ (sh (ch_user_beg ch) + nsh (ch_used ch) <= ch_user_beg ch - 16 \/ ch_user_beg ch + round_up (ch_used ch) 8 <= sh (ch_user_beg ch))
                 /\ (ch_user_beg ch + round_up (ch_used ch) 8 <= 2147446784 \/ 17594333495296 <= ch_user_beg ch - 16)).
    { acb. clear - Z2 Z3 Z6 Z1 ACEILB. destruct Z2 as (ZA & _ & ZB). unfold aapp, aapp_lo, aapp_hi, AIMG_TOP, ALOWSH_LO, AHI_LO in ZA, ZB. unfold sh, ASHADOW_BASE. Z.div_mod_to_equations. lia. }   (* [comment removed for export] *)
    repeat match goal with |- _ /\ _ => split end; try lia.
  Qed.

