                    cbn [cells_size csize Nat.add Nat.mul Z.of_nat Pos.of_succ_nat Pos.succ Pos.add Pos.mul length repeat map];
                    let Ha := fresh in intros ? Ha; apply Z; clear - Ha K; lia.
